// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "../i18n.js";
import "./backend_client.js";
import "./progress_modal.js";  // provides SolverUI.expectedCardCount

/* Chronexa Solver — Result panel.
 *
 *   SolverUI.Result.open({
 *     result:    SolveResponse,                  // per DATA_SHAPES.md
 *     mode:      "test" | "generate",
 *     school:    SchoolData,                     // the input — needed for totals
 *     onApply(newCards)                          // applied to APP.school.cards
 *     onDiscard()                                // restore previous
 *     onViewViolations(violations)               // open verification panel
 *     onClose()                                  // dismissed without action
 *   })
 *
 * Apply semantics:
 *   - Snapshot the existing APP.school.cards (deep copy).
 *   - Replace with SolveResponse.assignment mapped to the {lessonId, day, period,
 *     classroomId} card schema.
 *   - Discard restores the snapshot.
 *
 * The snapshot is owned by this module so a user can re-open and discard up
 * until they close the panel.
 */
(function (global) {
  "use strict";

  let host, dlg, refs, state;

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") n.className = attrs[k];
      else if (k.startsWith("on") && typeof attrs[k] === "function") n.addEventListener(k.slice(2), attrs[k]);
      else n.setAttribute(k, attrs[k]);
    }
    for (const c of kids) if (c != null) n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    return n;
  }

  function fmt(n) {
    if (n == null || !isFinite(n)) return "—";
    return Number(n).toLocaleString();
  }

  function build() {
    host = el("div", { class: "csu-backdrop", role: "presentation", "aria-hidden": "true" });
    dlg = el("section", {
      class: "csu-dialog csu-result",
      role: "dialog",
      "aria-modal": "true",
      "aria-labelledby": "csu-result-title",
    });

    const title = el("h2", { class: "csu-dialog__title", id: "csu-result-title" }, "Solver finished");
    const status = el("div", { class: "csu-result__status", id: "csu-result-status" }, "");

    const hero = el("div", { class: "csu-result__hero" });
    const placed   = el("div", { class: "csu-result__tile csu-result__tile--ok" });
    const relax    = el("div", { class: "csu-result__tile" });
    const soft     = el("div", { class: "csu-result__tile" });
    hero.append(placed, relax, soft);

    const reasons = el("div", { class: "csu-result__reasons", id: "csu-result-reasons", hidden: "" });

    const grid = el("div", { class: "csu-result__grid", id: "csu-result-grid" });
    const gridDetails = el("details", { class: "csu-result__details", id: "csu-result-grid-details" },
      el("summary", {}, "Lessons per period"),
      grid,
    );

    const apply = el("button", { type: "button", class: "chrx-btn chrx-btn--primary", onclick: doApply, id: "csu-result-apply" }, "Use this timetable");
    const retry = el("button", { type: "button", class: "chrx-btn", id: "csu-result-retry", onclick: () => { close(); window.dispatchEvent(new CustomEvent("app:generate")); } }, "Try again");
    const view  = el("button", { type: "button", class: "chrx-btn", onclick: doView }, "See issues");
    const relaxedBtn = el("button", { type: "button", class: "chrx-btn", id: "csu-result-relaxed", hidden: "",
      onclick: () => global.SolverUI.Relaxed && global.SolverUI.Relaxed.open({
        school: state.school, cards: assignmentToCards(state.result && state.result.assignment) }) }, "Relaxed conditions");
    const disc  = el("button", { type: "button", class: "chrx-btn", onclick: doDiscard, id: "csu-result-discard", hidden: "" }, "Undo apply");
    const closeBtn = el("button", { type: "button", class: "chrx-btn", id: "csu-result-close", onclick: doClose }, "Close");
    const actions = el("div", { class: "csu-dialog__actions" }, disc, view, relaxedBtn, retry, closeBtn, apply);

    const diagSection = el("div", { class: "csu-result__diag", id: "csu-result-diag" });

    dlg.append(title, status, hero, reasons, diagSection, gridDetails, actions);
    host.appendChild(dlg);
    document.body.appendChild(host);

    refs = { title, status, placed, relax, soft, reasons, grid, gridDetails, diagSection, apply, retry, view, disc, close: closeBtn, relaxedBtn };
  }

  function computeVerifiedClashes(school, result) {
    const solverHard = (result && result.stats && result.stats.hardConflicts) || 0;
    if (!school || !result || !Array.isArray(result.assignment)) return solverHard;
    try {
      const VPro = global.VerificationPanelPro;
      if (VPro && typeof VPro.countHardConflicts === "function") {
        const previewCards = mergePreservedCards(school, assignmentToCards(result.assignment));
        const previewSchool = Object.assign({}, school, { cards: previewCards });
        const verified = VPro.countHardConflicts(previewSchool);
        return Math.max(solverHard, verified);
      }
    } catch (_) {}
    return solverHard;
  }

  function qualitySummary(displayPenalty, placedCount) {
    const perCard = displayPenalty / Math.max(1, placedCount || 1);
    const pct = Math.max(15, Math.min(100, Math.round(100 - Math.min(85, Math.sqrt(Math.max(0, perCard)) * 1.4))));
    const word = pct >= 80 ? "Good" : (pct >= 60 ? "Fair" : "Needs work");
    return { pct, word };
  }

  function collectTopSoftReasons(school, result) {
    const out = [];
    try {
      const VPro = global.VerificationPanelPro;
      if (VPro && typeof VPro.collectViolations === "function" && school && result && Array.isArray(result.assignment)) {
        const previewCards = mergePreservedCards(school, assignmentToCards(result.assignment));
        const previewSchool = Object.assign({}, school, { cards: previewCards });
        const counts = new Map();
        for (const v of VPro.collectViolations(previewSchool)) {
          if (v.severity !== "soft") continue;
          const label = v.message || v.type || "Minor preference";
          counts.set(label, (counts.get(label) || 0) + 1);
        }
        const sorted = Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 3);
        for (const [msg, n] of sorted) out.push(n > 1 ? `${msg} (${n})` : msg);
      }
    } catch (_) {}
    return out;
  }

  function renderHero(result, totalLessons, verifiedHard) {
    const s = result.stats || {};
    refs.placed.innerHTML = "";
    refs.relax.innerHTML  = "";
    refs.soft.innerHTML   = "";

    const placedN = s.placed || 0;
    const unplacedN = Math.max(0, totalLessons - placedN);
    refs.placed.className = "csu-result__tile " + (unplacedN === 0 ? "csu-result__tile--ok" : "csu-result__tile--warn");
    refs.placed.append(
      el("div", { class: "csu-result__num" }, `${fmt(placedN)} / ${fmt(totalLessons)}`),
      el("div", { class: "csu-result__lbl" }, unplacedN === 0 ? "All lessons placed" : `${fmt(unplacedN)} left to place`),
    );

    const clashes = typeof verifiedHard === "number" ? verifiedHard : (s.hardConflicts || 0);
    refs.relax.className = "csu-result__tile " + (clashes === 0 ? "csu-result__tile--ok" : "csu-result__tile--bad");
    refs.relax.append(
      el("div", { class: "csu-result__num" }, fmt(clashes)),
      el("div", { class: "csu-result__lbl" }, clashes === 1 ? "clash" : "clashes"),
    );

    const displayPenalty = (typeof s.softScore === "number" && Number.isFinite(s.softScore))
      ? Math.max(0, Math.round(s.softScore < 0 ? -s.softScore : s.softScore))
      : 0;
    const q = qualitySummary(displayPenalty, placedN);
    refs.soft.className = "csu-result__tile " + (q.pct >= 80 ? "csu-result__tile--ok" : (q.pct >= 60 ? "" : "csu-result__tile--warn"));
    refs.soft.append(
      el("div", { class: "csu-result__num" }, `${q.word} (${q.pct}%)`),
      el("div", { class: "csu-result__lbl" }, "quality"),
    );
    refs.soft.title = s.phase2Note || `Soft score detail: ${fmt(displayPenalty)}`;

    if (refs.reasons) {
      const topReasons = collectTopSoftReasons(state && state.school, result);
      refs.reasons.innerHTML = "";
      if (topReasons.length) {
        refs.reasons.hidden = false;
        refs.reasons.appendChild(el("strong", {}, "What could be improved:"));
        const ul = el("ul", {});
        for (const r of topReasons) ul.appendChild(el("li", {}, r));
        refs.reasons.appendChild(ul);
      } else {
        refs.reasons.hidden = true;
      }
    }
  }

  function renderPerSlotGrid(result, school) {
    refs.grid.innerHTML = "";
    const periods = (school && school.bell && school.bell.periods) || [];
    if (!periods.length) return;
    const dayNames = (global.I18N && I18N.STRINGS && I18N.STRINGS.days && I18N.STRINGS.days.en) || ["Mon","Tue","Wed","Thu","Fri","Sat"];
    const periodIdxs = periods.map(p => p.index).sort((a, b) => a - b);

    // Build a (day,period) → count of placements.
    const buckets = new Map();
    for (const a of (result.assignment || [])) {
      const k = a.day + ":" + a.period;
      buckets.set(k, (buckets.get(k) || 0) + 1);
    }
    let maxCount = 1;
    for (const v of buckets.values()) if (v > maxCount) maxCount = v;

    const header = el("div", { class: "csu-result__gridRow csu-result__gridRow--head" });
    header.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--day" }, ""));
    for (const p of periodIdxs) {
      header.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--head" }, "P" + p));
    }
    refs.grid.appendChild(header);

    for (let d = 0; d < 6; d++) {
      const row = el("div", { class: "csu-result__gridRow" });
      row.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--day" }, dayNames[d] || ("D" + (d + 1))));
      for (const p of periodIdxs) {
        const k = d + ":" + p;
        const n = buckets.get(k) || 0;
        const intensity = n / maxCount;
        const cell = el("div", {
          class: "csu-result__gridCell",
          title: `${dayNames[d] || ("D" + (d + 1))} · P${p} · ${n} placements`,
          style: intensity > 0 ? `background: rgba(0,100,224,${(0.10 + 0.60 * intensity).toFixed(2)});` : "",
        }, n ? String(n) : "");
        row.appendChild(cell);
      }
      refs.grid.appendChild(row);
    }
  }

  // Phase 4 / Phase 5: render solver-authored diagnostics + weight calibration
  // suggestions. These are only present when the solver emits them (unplaced > 0
  // or placed > 0 respectively). Hidden entirely when absent.
  //
  // Diagnostics explain WHY each unplaceable lesson failed, broken down by
  // FAIL code (e.g. "TEACHER_CONFLICT: 12/26").
  // Weight suggestions show which soft-constraint categories had non-zero
  // violations, letting the user see what's driving the soft score.
  function renderDiagnostics(result) {
    refs.diagSection.innerHTML = "";
    const diag = result && Array.isArray(result.diagnostics) ? result.diagnostics : [];
    const ws   = result && result.weightSuggestions ? result.weightSuggestions : null;
    const issues = result && Array.isArray(result.validationIssues) ? result.validationIssues : [];
    const warnings = issues.filter(i => i.severity === "warn" && i.msg);

    if (!diag.length && !ws && !warnings.length) {
      refs.diagSection.style.display = "none";
      return;
    }
    refs.diagSection.style.display = "";

    const wrap = (title, bodyNode, isOpen) => {
      const hdr = el("div", { class: "csu-result__diagHdr" }, title);
      const box = el("details", { class: "csu-result__diagBox" }, hdr, bodyNode);
      if (isOpen) box.open = true;
      return box;
    };

    if (warnings.length) {
      const list = el("ul", { class: "csu-result__diagList" });
      for (const w of warnings) list.appendChild(el("li", {}, "⚠  " + w.msg));
      refs.diagSection.appendChild(wrap("Input warnings (" + warnings.length + ")", list, true));
    }

    if (diag.length) {
      // Make raw FAIL codes (e.g. "class_conflict: 23/42") readable.
      const REASON_WORDS = {
        teacher_conflict: "teacher already teaching",
        teacher_unavailable: "teacher off that period",
        teacher_max_per_day: "teacher daily limit",
        class_conflict: "class already in another lesson",
        class_unavailable: "class off that period",
        class_max_per_day: "class daily limit",
        room_conflict: "room taken",
        room_unavailable: "room off that period",
        subject_daily_limit: "subject daily limit",
        subject_daily_min_violation: "daily-spread rule",
        class_bell_period_invalid: "outside class hours",
        fixed_slot_mismatch: "fixed-slot clash",
        required_room_type: "no room of required type",
      };
      const humanize = (reason) => (reason || "unplaceable").replace(
        /[a-z_]+/g, (m) => REASON_WORDS[m] || m.replace(/_/g, " "));

      const impossible = diag.filter(d => d.verdict === "IMPOSSIBLE");
      const contention = diag.filter(d => d.verdict !== "IMPOSSIBLE");

      // Summary: the whole point — separate "fix the file" from "try again".
      const summary = impossible.length
        ? `⛔ ${impossible.length} cannot be placed in ANY timetable — these need a file change (free the teacher, add a room, or relax a fixed slot). ` +
          (contention.length ? `The other ${contention.length} are contention (a better run may place them).` : "")
        : `✓ None are impossible — your file is feasible. These ${contention.length} are contention: the solver couldn't fit them in this run. Re-running (or accepting the best of more branches) may place them.`;
      refs.diagSection.appendChild(el("div", { class: "csu-result__diagTip" }, summary));

      const list = el("ul", { class: "csu-result__diagList" });
      // Show impossible (actionable) first, then contention. Cap at 12 visible.
      const ordered = impossible.concat(contention);
      const cap = Math.min(ordered.length, 12);
      for (let i = 0; i < cap; i++) {
        const d = ordered[i];
        const name = d.label || d.lessonId || ("lesson " + (d.lessonIdx + 1));
        const isImp = d.verdict === "IMPOSSIBLE";
        const badge = el("span", {
          class: "csu-result__diagBadge",
          style: "font-size:0.75em;font-weight:600;margin-right:6px;padding:1px 6px;border-radius:4px;" +
            (isImp ? "background:#fde2e2;color:#b42318;" : "background:#fef3c7;color:#92400e;"),
        }, isImp ? "FIX FILE" : "CONTENTION");
        list.appendChild(el("li", {},
          badge,
          el("strong", {}, name),
          el("br"),
          el("span", { class: "csu-result__diagReason" }, humanize(d.reason)),
        ));
      }
      if (ordered.length > cap) {
        list.appendChild(el("li", { class: "csu-result__diagMore" },
          `…and ${ordered.length - cap} more. Open "View violations" for the full list.`));
      }
      refs.diagSection.appendChild(wrap("Unplaceable lessons (" + diag.length + ")", list, true));
    }

    if (ws) {
      const keys = Object.keys(ws).sort((a, b) => ws[b] - ws[a]);
      if (keys.length) {
        const list = el("ul", { class: "csu-result__diagList" });
        for (const k of keys) {
          const v = ws[k];
          const label = k.replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase()).trim();
          list.appendChild(el("li", {},
            el("strong", {}, label),
            el("span", { class: "csu-result__diagReason" }, " — " + Number(v).toLocaleString() + " penalty points"),
          ));
        }
        const tip = el("div", { class: "csu-result__diagTip" },
          "These are the largest contributors to your soft score. Increasing the corresponding weight in Solver Parameters will prioritize them in the next run.");
        refs.diagSection.appendChild(wrap("Soft score breakdown", list));
        refs.diagSection.lastChild.appendChild(tip);
      }
    }
  }

  function renderRelaxedButton() {
    const R = global.SolverUI && global.SolverUI.Relaxed;
    const a = state.result && state.result.assignment;
    let n = 0;
    try { if (R && state.school && Array.isArray(a)) n = R.report(state.school, assignmentToCards(a)).total; }
    catch (e) { console.warn("[relaxed report]", e); }
    refs.relaxedBtn.hidden = !n;
    refs.relaxedBtn.textContent = `Relaxed conditions (${n})`;
  }

  function assignmentToCards(assignment) {
    if (!Array.isArray(assignment)) return [];
    // Lock state comes from the LIVE timetable: "Add unplaced only" solves on a copy whose placed
    // cards are temporarily hard-locked, and those locks must never reach the applied cards.
    const liveCards = global.APP && global.APP.school && Array.isArray(global.APP.school.cards) ? global.APP.school.cards : null;
    const origCards = liveCards || (state && state.school && state.school.cards) || [];
    const origLocked = new Set(
      origCards
        .filter((c) => c && c.locked)
        .map((c) => `${String(c.lessonId).replace(/#\d+$/, "")}|${c.day}|${c.period}`)
    );
    const out = [];
    for (const a of assignment) {
      const baseId = String(a.lessonId).replace(/#\d+$/, "");
      // Solver output may echo locks it added internally (stage 2 of "Add unplaced only" hard-locks
      // every draft card), so a.locked is NOT user intent: lock state comes from the live school only.
      const isLocked = origLocked.has(`${baseId}|${a.day}|${a.period}`)
        || origLocked.has(`${a.lessonId}|${a.day}|${a.period}`);
      out.push({
        lessonId: a.lessonId,
        day: a.day,
        period: a.period,
        classroomId: a.classroomId || null,
        ...(isLocked ? { locked: true } : {}),
      });
    }
    return out;
  }

  function cloneCards(cards) {
    const core = global.APP && global.APP.__chronexaMutateCore;
    if (core && typeof core.cloneValue === "function") return core.cloneValue(cards);
    if (typeof global.structuredClone === "function") return global.structuredClone(cards);
    return JSON.parse(JSON.stringify(cards));
  }

  function mutateResultCards(label, school, cards) {
    const apply = (target) => { target.cards = cloneCards(cards); };
    if (school && school === global.APP?.school && typeof global.APP?.mutate === "function") {
      return global.APP.mutate(label, apply);
    }
    // Result previews can be opened with a detached school in tests or by a
    // caller preparing a preview. Keep that API usable without recording a
    // transaction against a different live school.
    if (school) apply(school);
  }

  // P1: Preserve any non-lesson / duty / orphan cards that the solver does not manage.
  function mergePreservedCards(school, solverCards) {
    const out = Array.isArray(solverCards) ? solverCards.slice() : [];
    if (!school || !Array.isArray(school.cards)) return out;
    const lessonIds = new Set((school.lessons || []).map(l => String(l.id)));
    for (const c of school.cards) {
      const baseId = String(c.lessonId || "").replace(/#\d+$/, "");
      if (!lessonIds.has(baseId)) out.push(cloneCards(c));
    }
    return out;
  }

  // P1: Count actual covered lesson-periods (avoiding false warnings when aSc XML
  // splits a double-period lesson into 2 separate 1-period <card> elements while the
  // solver emits 1 card with span=2).
  function coveredLessonSlots(school, cards) {
    if (!Array.isArray(cards) || !cards.length) return 0;
    const byId = new Map((school && school.lessons || []).map(l => [String(l.id), l]));
    const perLesson = new Map();
    for (const c of cards) {
      const baseId = String(c.lessonId || "").replace(/#\d+$/, "");
      const l = byId.get(baseId);
      const span = Math.max(1, Number(c.span) || (l ? Number(l.periodsPerCard) : 1) || 1);
      // If XML stored 2 separate <card>s for a ppw=2/ppc=2 lesson, cap by periodsPerWeek.
      const cur = perLesson.get(baseId) || 0;
      const cap = l && l.periodsPerWeek ? Number(l.periodsPerWeek) : (cur + span);
      perLesson.set(baseId, Math.min(cap, cur + span));
    }
    let total = 0;
    for (const v of perLesson.values()) total += v;
    return total;
  }

  function applyImmediately() {
    if (!state) return;
    const targetSchool = global.APP?.school || state.school;
    const newCards = mergePreservedCards(targetSchool, assignmentToCards(state.result.assignment));
    if (state.school && !state.snapshot) {
      state.snapshot = cloneCards(Array.isArray(state.school.cards) ? state.school.cards : []);
    }
    mutateResultCards("Apply solver timetable", targetSchool, newCards);
    if (state.school && state.school !== global.APP?.school) state.school.cards = cloneCards(newCards);
    state.applied = true;
    state.discarded = false;
    refs.apply.disabled = true;
    refs.disc.hidden = false;
    refs.disc.disabled = false;
    refs.status.textContent = "Applied to your timetable.";
    refs.status.style.color = "var(--chrx-green)";
    try {
      const editorRoot = document.querySelector(".chrx-editor");
      if (editorRoot && global.Editor && global.Editor.render) global.Editor.render(editorRoot);
      const pendRoot = document.querySelector(".chrx-pending-strip");
      if (pendRoot && global.PendingStrip && global.PendingStrip.render) global.PendingStrip.render(pendRoot);
      if (global.EditorActivator && global.EditorActivator.updatePendingCount) global.EditorActivator.updatePendingCount();
      if (global.Editor && global.Editor.updateUnplacedCount) global.Editor.updateUnplacedCount();
    } catch (e) { console.warn("[result_panel] post-apply re-render failed", e); }
    try { window.dispatchEvent(new CustomEvent("app:solve-applied")); } catch {}
    if (state.onApply) try { state.onApply(newCards); } catch (e) { console.error(e); }
  }

  function isDestructiveApply() {
    if (!state || !state.school) return false;
    const existing = Array.isArray(state.school.cards) ? state.school.cards : [];
    const assignment = (state.result && state.result.assignment) || [];
    if (!existing.length) return false;
    if (!assignment.length) return true;
    // A 100%-placed run with 0 unplaced lessons is never destructive.
    const expected = global.SolverUI && global.SolverUI.expectedCardCount
      ? global.SolverUI.expectedCardCount(state.school)
      : 0;
    const unplaced = (state.result.stats && state.result.stats.unplaced) || 0;
    if (unplaced === 0 && expected > 0 && assignment.length >= expected) return false;
    const haveSlots = coveredLessonSlots(state.school, existing);
    const newSlots  = coveredLessonSlots(state.school, mergePreservedCards(state.school, assignmentToCards(assignment)));
    return newSlots < haveSlots;
  }

  function confirmDestructiveApply() {
    if (document.getElementById("chrx-apply-confirm")) return;
    const haveSlots = coveredLessonSlots(state.school, state.school.cards || []);
    const newSlots  = coveredLessonSlots(state.school, mergePreservedCards(state.school, assignmentToCards(state.result.assignment || [])));
    const lost = Math.max(1, haveSlots - newSlots);
    const hard = computeVerifiedClashes(state.school, state.result);
    const overlay = document.createElement("div");
    overlay.id = "chrx-apply-confirm";
    overlay.style.cssText = "position:fixed;inset:0;background:rgba(15,23,42,.55);display:flex;align-items:center;justify-content:center;z-index:10001;font-family:var(--chrx-font-sans,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif);";
    overlay.innerHTML = ''
      + '<div role="alertdialog" aria-modal="true" style="background:var(--chrx-bg-panel,#fff);color:var(--chrx-fg,#1d1d1f);border-radius:14px;box-shadow:0 24px 64px rgba(15,23,42,.28);padding:24px 26px;max-width:460px;width:calc(100% - 32px);">'
      +   '<h2 style="font-size:17px;font-weight:700;color:var(--chrx-fg,#1d1d1f);margin:0 0 8px;">Replace your current timetable?</h2>'
      +   `<p style="font-size:13.5px;line-height:1.55;color:var(--chrx-fg-secondary,#515154);margin:0 0 18px;">This run leaves <strong>${lost}</strong> fewer period${lost === 1 ? '' : 's'} placed than your current timetable` + (hard > 0 ? ` and has <strong>${hard} clash${hard === 1 ? '' : 'es'}</strong>` : '') + `. You can still undo after applying.</p>`
      +   '<div style="display:flex;gap:8px;justify-content:flex-end;">'
      +     '<button type="button" data-cancel class="chrx-btn">Cancel</button>'
      +     '<button type="button" data-confirm class="chrx-btn chrx-btn--primary">Replace anyway</button>'
      +   '</div>'
      + '</div>';
    document.body.appendChild(overlay);
    overlay.querySelector("[data-cancel]").focus();
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    overlay.querySelector("[data-cancel]").onclick = () => overlay.remove();
    overlay.querySelector("[data-confirm]").onclick = () => { overlay.remove(); applyImmediately(); };
  }
  function doApply() {
    if (!state) return;
    if (isDestructiveApply()) { confirmDestructiveApply(); return; }
    applyImmediately();
  }
  function doDiscard() {
    if (!state) return;
    if (state.school && state.snapshot != null) {
      mutateResultCards("Discard solver timetable", global.APP?.school || state.school, state.snapshot);
      if (state.school && state.school !== global.APP?.school) state.school.cards = cloneCards(state.snapshot);
      state.snapshot = null;
    }
    state.discarded = true;
    refs.apply.disabled = false;
    refs.disc.disabled = true;
    refs.status.textContent = "Discarded — your previous timetable is restored.";
    refs.status.style.color = "var(--chrx-orange)";
    try {
      const editorRoot = document.querySelector(".chrx-editor");
      if (editorRoot && global.Editor && global.Editor.render) global.Editor.render(editorRoot);
      const pendRoot = document.querySelector(".chrx-pending-strip");
      if (pendRoot && global.PendingStrip && global.PendingStrip.render) global.PendingStrip.render(pendRoot);
      if (global.EditorActivator && global.EditorActivator.updatePendingCount) global.EditorActivator.updatePendingCount();
    } catch (_) {}
    if (state.onDiscard) try { state.onDiscard(); } catch (e) { console.error(e); }
  }
  function doView() {
    if (!state) return;
    const v = (state.result && state.result.violations) || [];
    // Auto-apply on view-violations too (same intent as close).
    if (canAutoApply()) doApply();
    close();
    if (state.onViewViolations) try { state.onViewViolations(v); } catch (e) { console.error(e); }
  }
  function canAutoApply() {
    if (!state) return false;
    if (state.mode === "test") return false;
    if (state.applied || state.discarded) return false;
    const r = state.result;
    if (!r) return false;
    const a = r.assignment;
    if (!Array.isArray(a) || a.length === 0) return false;
    // INFEASIBLE with zero placements — never auto-apply.
    if (r.status === "INFEASIBLE" && a.length === 0) return false;
    // scrubbedConflicts = actual constraint violations in the placed
    // schedule (teacher overlaps, class overlaps, etc.). If any exist,
    // block auto-apply. Note: hardConflicts in the solver output counts
    // UNPLACED lessons, not violations in placed cards.
    const scrubbed = (r.stats && r.stats.scrubbedConflicts) || 0;
    if (scrubbed > 0) return false;
    // TIMEOUT is the *normal* outcome for medium-to-large schools. The solver
    // always uses its full time budget and returns the best result found.
    // Auto-apply if the result placed ≥ 90% of cards.
    const placed = (r.stats && r.stats.placed) || a.length;
    const unplaced = (r.stats && r.stats.unplaced) || 0;
    const total = placed + unplaced;
    if (total > 0 && placed / total < 0.90) return false;
    // Don't silently overwrite a working timetable with a much smaller one
    // (protect against solver regression). Threshold: result must have at
    // least 85% of the existing card count.
    const before = (state.school && state.school.cards && state.school.cards.length) || 0;
    if (before > 0 && a.length < before * 0.85) return false;
    return true;
  }
  function doClose() {
    // Implicit-apply: if the solver produced placements and the user
    // didn't explicitly Discard, treat Close as "keep these cards" so
    // a successful run isn't silently thrown away.
    if (canAutoApply()) doApply();
    close();
    if (state && state.onClose) try { state.onClose(); } catch (e) { console.error(e); }
    state = null;
  }

  function open(opts) {
    if (!host) build();
    state = {
      result: opts.result || { stats: {}, assignment: [], violations: [] },
      school: opts.school || null,
      mode:   opts.mode || "generate",
      onApply: opts.onApply,
      onDiscard: opts.onDiscard,
      onViewViolations: opts.onViewViolations,
      onClose: opts.onClose,
      snapshot: null,
    };
    const status = state.result.status || "DONE";
   // Hero denominator should be total expected cards (lessons × periodsPerWeek),
   // not lesson count — a single lesson can spawn many cards per week.
   const expectedCards = global.SolverUI.expectedCardCount(state.school);
    const placedNum  = (state.result.stats && state.result.stats.placed)   || 0;
    const unplacedNm = (state.result.stats && state.result.stats.unplaced) || 0;
    const totalLessons = expectedCards || (placedNum + unplacedNm);
    // Verdict headline — one plain sentence shared with Ask + Work.
    const pct = totalLessons > 0 ? placedNum / totalLessons : 1;
    if (state.mode === "test") {
      refs.title.textContent = "Check finished";
    } else if (pct >= 1) {
      refs.title.textContent = "Timetable ready — everything placed";
    } else if (pct >= 0.9) {
      refs.title.textContent = `Almost there — ${fmt(placedNum)} of ${fmt(totalLessons)} placed`;
    } else {
      refs.title.textContent = `Needs attention — ${fmt(placedNum)} of ${fmt(totalLessons)} placed`;
    }
    const durSec = (state.result.stats && state.result.stats.durationMs) ? Math.max(1, Math.round(state.result.stats.durationMs / 1000)) : 0;
    const verifiedHard = computeVerifiedClashes(state.school, state.result);
    refs.status.textContent = durSec ? `Finished in ${durSec}s` : "Finished";
    refs.status.style.color = (verifiedHard === 0 && unplacedNm === 0) ? "var(--chrx-green)" : "var(--chrx-amber)";
    refs.apply.disabled = state.mode === "test";
    refs.disc.hidden = true;
    refs.disc.disabled = true;
    if (refs.gridDetails) refs.gridDetails.open = false;
    renderHero(state.result, totalLessons, verifiedHard);
    renderPerSlotGrid(state.result, state.school);
    renderDiagnostics(state.result);
    renderRelaxedButton();

    const bad = (status === "INFEASIBLE" || isDestructiveApply());
    if (refs.apply) {
      refs.apply.classList.toggle("is-warning", bad);
      refs.apply.style.background = "";
      refs.apply.style.color      = "";
      refs.apply.style.border     = "";
    }

    host.classList.add("is-open");
    host.setAttribute("aria-hidden", "false");
    // Default focus to Close on dangerous results (Discard is disabled until
    // something is applied). For clean runs, focus Apply so Enter ships it.
    requestAnimationFrame(() => {
      const target = bad ? refs.close : (refs.apply && !refs.apply.disabled ? refs.apply : refs.close);
      if (target && typeof target.focus === "function") target.focus();
    });
  }
  function close() {
    if (!host) return;
    host.classList.remove("is-open");
    host.setAttribute("aria-hidden", "true");
  }

  global.SolverUI = global.SolverUI || {};
  global.SolverUI.Result = { open, close };

  if (typeof document !== "undefined") {
    document.addEventListener("app:school-changed", (e) => {
      const source = e && e.detail && e.detail.source;
      if (source === "undo" || source === "redo") {
        try {
          const editorRoot = document.querySelector(".chrx-editor");
          if (editorRoot && global.Editor && global.Editor.render) global.Editor.render(editorRoot);
          const pendRoot = document.querySelector(".chrx-pending-strip");
          if (pendRoot && global.PendingStrip && global.PendingStrip.render) global.PendingStrip.render(pendRoot);
          if (global.EditorActivator && global.EditorActivator.updatePendingCount) global.EditorActivator.updatePendingCount();
        } catch (_) {}
      }
    });
  }
})(typeof window !== "undefined" ? window : globalThis);
